class Solution:
    def countSubstrings(self, s: str, t: str) -> int:
        m, n = len(s), len(t)
        ans = 0
        for i in range(m):
            for j in range(n):
                diff = 0
                for k in range(min(m - i, n - j)):
                    if s[i + k] != t[j + k]:
                        diff += 1
                        if diff > 1:
                            break
                    if diff == 1:
                        ans += 1
        return ans

