        for (int i = 0; i < m; ++i)
            for (int j = 0; j < n; ++j)
                for (int k = 0, diff = 0; k < min(m - i, n - j); ++k) {
                    if (s[i + k] != t[j + k] && ++diff > 1) break;
                    ans += diff == 1;
                }
        return ans;
    }
};

